from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.f = []
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "img" and "alt" not in a:
            self.f.append(a["src"])
p = P()
p.feed('<img src="x.png"><img src="y.png" alt="">')
print(p.f)
